mapper.insert:
insert into user_asset_collection(goods_id, address, num, update_time)
select #{goodsId}, #{address}, ifnull(sum(t.num), 0), #{time}
from user_asset_token t
where t.goods_id = #{goodsId}
  and t.address = #{address}

mapper.update:
update user_asset_collection c
set c.num         = (select ifnull(sum(t.num), 0)
                     from user_asset_token t
                     where c.goods_id = t.goods_id
                       and c.address = t.address),
    c.update_time = #{time}
where c.goods_id = #{goodsId}
  and c.address = #{address}

mapper.select:
select *
from user_asset_collection
where goods_id = #{goodsId}
  and address = #{address}

select uac.*
from user_asset_collection uac
left join goods_spu spu on uac.goods_id = spu.goods_id

    uac.num > 0

        and uac.address = #{address}


        and spu.type = #{spuType}


        and (
        uac.goods_id = #{vague}
        or uac.address = #{vague}
        or spu.name like CONCAT('%', #{vague}, '%')
        )


order by uac.update_time desc
